        form("want.same.4", "want.same", "You need to sleep.", "Necesito ___.", ["dormir", "que duerma"], [0], "You need it and you do it: the infinitive."),

        form("subject.feel.1", "subject.feel", "You're happy to be here.", "Me alegro de ___ aquí.", ["estar", "que esté"], [0], "You feel it and you're the one here: the infinitive. Me alegro de que esté aquí is about someone else."),
        form("subject.feel.2", "subject.feel", "You're happy your sister is here.", "Me alegro de que mi hermana ___ aquí.", ["está", "esté"], [1], "Someone else: que + subjunctive."),
        form("subject.feel.3", "subject.feel", "You apologize for being late.", "Siento ___ tarde.", ["llegar", "que llegue"], [0], "You're the one who's late: siento llegar tarde. Siento que llegues tarde: sorry that you are."),
        form("subject.feel.4", "subject.feel", "You're scared of getting lost.", "Tengo miedo de ___.", ["perderme", "que me pierda"], [0], "Same person: the infinitive, with the pronoun on the end."),

        form("subject.prep.1", "subject.prep", "You left without saying anything.", "Me fui sin ___ nada.", ["decir", "que dijera"], [0], "You left and you didn't say: sin + infinitive."),
        form("subject.prep.2", "subject.prep", "He left; nobody saw him.", "Salió sin que nadie lo ___.", ["vio", "viera"], [1], "Someone else (nadie): sin que + subjunctive, always."),
        form("subject.prep.3", "subject.prep", "Wash your hands, then eat.", "Lávate las manos antes de ___.", ["comer", "que comas"], [0], "You wash and you eat: antes de + infinitive. Antes de que comas sounds like someone else is eating."),
        form("subject.prep.4", "subject.prep", "You explain so your student gets it.", "Te lo explico para que lo ___.", ["entiendes", "entiendas"], [1], "Someone else: para que + subjunctive."),

        form("subject.impersonal.1", "subject.impersonal", "General health advice, for anyone.", "Es importante ___ agua.", ["beber", "que bebas"], [0], "About people in general: the infinitive. Es importante que bebas agua is correct too, but it's about you."),
        form("subject.impersonal.2", "subject.impersonal", "Your friend is sick; you tell them.", "Es importante que ___ agua.", ["bebes", "bebas"], [1], "A particular person after es importante que: subjunctive."),
        form("subject.impersonal.3", "subject.impersonal", "You're talking to your sick friend.", "Es importante ___ agua.", ["beber", "que bebas"], [0, 1], "Both are right. Que bebas points at your friend; beber is general advice that includes them."),
        meaning("subject.impersonal.4", "subject.impersonal", "A sign at the pool.", "Es necesario ducharse antes de entrar.", ["Everyone has to shower first.", "One particular person has to shower."], 0, "The infinitive: everyone."),
        meaning("subject.impersonal.5", "subject.impersonal", "The coach, to one swimmer.", "Es necesario que te duches antes de entrar.", ["Everyone has to shower first.", "You, the swimmer, have to shower."], 1, "Que + subjunctive: a particular person."),
        form("subject.impersonal.6", "subject.impersonal", "You decide you'd better leave.", "Es mejor que me ___.", ["voy", "vaya"], [1], "About yourself, que + subjunctive is fine and very common: es mejor que me vaya."),
        form("subject.impersonal.7", "subject.impersonal", "Same idea, said another way.", "Es mejor ___.", ["irme", "que me vaya"], [0, 1], "Both are right: es mejor irme and es mejor que me vaya. With no other person around, both are about you."),
        form("subject.impersonal.8", "subject.impersonal", "The rules for every student.", "Hace falta ___ el formulario.", ["llenar", "que llenes"], [0], "For everyone: the infinitive. Que llenes would be one particular student."),
        form("subject.impersonal.9", "subject.impersonal", "Your mom reminds you.", "Hace falta que ___ el formulario.", ["llenas", "llenes"], [1], "A particular person after hace falta que: subjunctive."),

        form("subject.doer.1", "subject.doer", "You love to dance.", "Me encanta ___.", ["bailar", "que baile"], [0], "You love it and you dance: the infinitive."),
        form("subject.doer.2", "subject.doer", "You love it when your partner dances.", "Me encanta que mi pareja ___.", ["baila", "baile"], [1], "Someone else dances: que + subjunctive."),
        form("subject.doer.3", "subject.doer", "You ask your friend to wait.", "¿Te importa ___ un momento?", ["esperar", "que espere"], [0], "Your friend minds and your friend waits: the infinitive. ¿Te importa que espere? means do you mind if I wait."),
        meaning("subject.doer.4", "subject.doer", "At the doctor's office.", "¿Le importa que espere aquí?", ["Do you mind if I wait here?", "Do you mind waiting here?"], 0, "Que + subjunctive: someone other than the one who minds, here me."),

        form("subject.overlap.1", "subject.overlap", "You want the two of you to go together.", "Quiero que ___ juntos.", ["vamos", "vayamos"], [1], "Yo and nosotros are different subjects, so que + subjunctive."),
        form("subject.overlap.2", "subject.overlap", "Your team won.", "Me alegro de que ___ ganado.", ["hemos", "hayamos"], [1], "Nosotros isn't just yo: que + subjunctive is right."),
        meaning("subject.overlap.3", "subject.overlap", "Leaving a party.", "Quiero que nos vayamos ya.", ["I want us to leave now.", "I want to leave now, alone."], 0, "Nosotros: you and the others."),
        form("subject.overlap.5", "subject.overlap", "You all want to go yourselves.", "Queremos ___.", ["ir", "que vayamos"], [0], "We want and we go: exactly the same people, so the infinitive. Queremos que vayamos is wrong."),
        form("subject.overlap.6", "subject.overlap", "Your team won; you're glad.", "Me alegro de ___ ganado.", ["haber", "que hayamos"], [0, 1], "Both are right. As part of the team, me alegro de haber ganado works; que hayamos ganado says 'we' outright."),
        meaning("subject.overlap.4", "subject.overlap", "Before a job interview.", "Espero que me vaya bien.", ["I hope it goes well for me.", "I hope I leave well."], 0, "The subject is it (me va bien), not I, so que is needed."),

        form("subject.object.1", "subject.object", "Your parents let you go out.", "Mis papás me dejan ___.", ["salir", "que salga"], [0, 1], "Both are right: me dejan salir, me dejan que salga."),
        form("subject.object.2", "subject.object", "You forbid your brother to go out.", "Te prohíbo ___ sin permiso.", ["salir", "que salgas"], [0, 1], "Both are right with prohibir, dejar, permitir, mandar."),
        form("subject.object.3", "subject.object", "You ask your friend to come.", "Te pido que ___.", ["vienes", "vengas"], [1], "Pedir prefers que + subjunctive."),
        meaning("subject.object.4", "subject.object", "In class.", "Pidió salir.", ["He asked to leave, himself.", "He asked someone else to leave."], 0, "Pedir + infinitive: the one who asks does it."),

        form("subject.allowed.1", "subject.allowed", "You hope you can make it; it isn't up to you.", "Espero que ___ ir.", ["puedo", "pueda"], [1], "Espero que pueda ir is correct and very common, even though it's the same person."),
        form("subject.allowed.2", "subject.allowed", "Same hope.", "Espero ___ ir.", ["poder", "que pueda"], [0, 1], "Both are right. Espero poder ir is tidier; espero que pueda ir is what many people say."),
        form("subject.allowed.3", "subject.allowed", "Yesterday you worked until you got tired.", "Trabajé hasta que me ___.", ["cansé", "cansara"], [0], "Hasta que with the same person is normal; it happened, so indicative. Trabajé hasta cansarme is just as standard."),
        form("subject.allowed.4", "subject.allowed", "Don't leave before you finish.", "No te vayas hasta que ___.", ["terminas", "termines"], [1], "Still to come: subjunctive. Hasta terminar works too."),
        form("subject.allowed.5", "subject.allowed", "You'll call when you arrive.", "Te llamo cuando ___.", ["llego", "llegue"], [1], "The same person with cuando + subjunctive is normal. Al llegar (on arriving) says it with an infinitive."),

        form("subject.belief.1", "subject.belief", "You think you're right.", "Creo que ___ razón.", ["tengo", "tenga"], [0], "Believing keeps que + indicative, even for the same person."),
        form("subject.belief.2", "subject.belief", "He says he's tired.", "Dice que ___ cansado.", ["está", "esté"], [0], "Saying passes on news: indicative."),
        meaning("subject.belief.3", "subject.belief", "In a formal letter.", "Creo tener razón.", ["I believe I'm right (formal).", "I want to be right."], 0, "Creer + infinitive exists, but it's formal. Creo que tengo razón is the everyday way."),

        form("subject.belief.4", "subject.belief", "You doubt you're right yourself.", "No creo que ___ razón.", ["tengo", "tenga"], [1], "Negated belief: subjunctive, even about yourself."),

        form("subject.perfect.1", "subject.perfect", "You're glad you came.", "Me alegro de ___ venido.", ["haber", "que haya"], [0], "Same person, something already done: haber + participle."),
        form("subject.perfect.2", "subject.perfect", "You're glad your friend came.", "Me alegro de que ___ venido.", ["has", "hayas"], [1], "Someone else: que + perfect subjunctive."),
        form("subject.perfect.3", "subject.perfect", "You're sorry you didn't call.", "Siento no ___ llamado.", ["haber", "haya"], [0], "Same person: no haber + participle."),

        // Wanting
        form("want.esperaA.1", "want.esperaA", "Wait for your dad.", "Espera a que ___ tu papá.", ["llega", "llegue"], [1], "Waiting for something that hasn't happened: subjunctive."),
        form("want.esperaA.2", "want.esperaA", "Yesterday you waited for the rain to stop.", "Esperamos a que ___ de llover.", ["dejó", "dejara"], [1], "Still the subjunctive in the past, and the imperfect after a past verb."),
        meaning("want.esperaA.3", "want.esperaA", "At the bus stop.", "Espera a que llegue.", ["Wait until he arrives.", "Hope he arrives."], 0, "Esperar a que = wait until. Espero que llegue = I hope he arrives."),
        form("want.meaning.4", "want.meaning", "He claims he's innocent.", "Insiste en que ___ inocente.", ["es", "sea"], [0], "Insisting it's so: indicative."),
        form("want.meaning.5", "want.meaning", "She demands you arrive early.", "Insiste en que ___ temprano.", ["llegamos", "lleguemos"], [1], "Insisting someone do it: subjunctive."),
        form("want.meaning.6", "want.meaning", "Remind him to buy bread.", "Recuérdale que ___ pan.", ["compra", "compre"], [1], "Reminding someone to do it: subjunctive. Te recuerdo que hay examen (a fact): indicative."),
        form("want.meaning.7", "want.meaning", "She complained you arrived late.", "Se quejó de que ___ tarde.", ["llegué", "llegara"], [0, 1], "Both are right. Llegué reports the fact and complains; llegara is the complaint only. The same goes for reprochar, echar en cara, presumir de."),
        form("want.convencer.1", "want.convencer", "You persuaded him to come.", "Lo convencí de que ___.", ["vino", "viniera"], [1], "Persuading someone to do it: subjunctive."),
        form("want.convencer.2", "want.convencer", "You're sure he's coming.", "Estoy convencido de que ___.", ["viene", "venga"], [0], "Estar convencido = be sure: indicative."),
        meaning("want.convencer.3", "want.convencer", "An argument with a friend.", "Lo convencí de que era verdad.", ["I convinced him it was true.", "I persuaded him to make it true."], 0, "Convencer de que + indicative: convincing of a fact."),

        // Feelings
        form("feel.true.3", "feel.true", "Your kids are happy, and you love it.", "Me encanta que mis hijos ___ felices.", ["son", "sean"], [1], "True, but you're reacting to it: subjunctive."),
        form("feel.temerse.3", "feel.temerse", "Thank goodness you came.", "Menos mal que ___.", ["viniste", "vinieras"], [0], "Menos mal que: a relief about a fact, indicative."),
        form("feel.hecho.1", "feel.hecho", "He's young, but that doesn't matter.", "El hecho de que ___ joven no importa.", ["es", "sea"], [0, 1], "The subjunctive is usual (a given fact as background). The indicative is heard when the fact is news."),
        form("feel.hecho.2", "feel.hecho", "That you're here makes you happy.", "Que ___ aquí me alegra.", ["estás", "estés"], [1], "A que clause at the start is background: subjunctive."),
        form("feel.hecho.3", "feel.hecho", "You didn't come, and it bothered me.", "El que no ___ venido me molestó.", ["has", "hayas"], [1], "El que + clause works like el hecho de que: subjunctive."),
        form("feel.lo.1", "feel.lo", "The problem: there's no money.", "Lo malo es que no ___ dinero.", ["tenemos", "tengamos"], [0, 1], "Both are right. Tenemos tells it as news; tengamos treats it as a given and reacts to it."),
        form("feel.lo.4", "feel.lo", "The truth is you're tired.", "Lo cierto es que ___ cansado.", ["estoy", "esté"], [0], "Lo cierto es que states a fact: indicative."),
        form("feel.lo.2", "feel.lo", "The best thing is for you to rest.", "Lo mejor es que ___.", ["descansas", "descanses"], [1], "What would be best: subjunctive."),
        form("feel.lo.3", "feel.lo", "After an accident: you're fine, that's what matters.", "Lo importante es que ___ bien.", ["estás", "estés"], [0, 1], "Both are right. Estás: relief about a fact. Estés: what matters is that you be well."),

        // Doubt
        form("doubt.nodudo.2", "doubt.nodudo", "You're sure he'll help.", "No dudo que te ___.", ["ayudará", "ayude"], [0, 1], "Both are right; the indicative is the usual."),
        form("doubt.nodudo.3", "doubt.nodudo", "You admit it's hard.", "No niego que ___ difícil.", ["es", "sea"], [0, 1], "No niego que: both moods work."),
        form("doubt.certain.3", "doubt.certain", "There's no doubt you're right.", "No hay duda de que ___ razón.", ["tienes", "tengas"], [0], "Certainty: indicative."),
        form("doubt.mentira.1", "doubt.mentira", "It's a lie that he stole.", "Es mentira que ___ robado.", ["ha", "haya"], [1], "Es mentira que rejects it: subjunctive."),
        form("doubt.mentira.2", "doubt.mentira", "It's no lie: he works a lot.", "No es mentira que ___ mucho.", ["trabaja", "trabaje"], [0], "No es mentira que claims it: indicative."),
        form("doubt.mentira.3", "doubt.mentira", "You think he said it.", "¿Niegas que lo ___?", ["dijiste", "dijeras"], [0, 1], "Both are right. Dijiste: the speaker thinks you did. Dijeras: a neutral question."),
        form("doubt.reason.1", "doubt.reason", "It's not that you don't want to.", "No es que no ___, es que no puedo.", ["quiero", "quiera"], [1], "A rejected reason: subjunctive."),
        form("doubt.reason.2", "doubt.reason", "Your real reason: you're tired.", "Es que ___ cansado.", ["estoy", "esté"], [0], "Es que gives the reason: indicative."),
        form("doubt.reason.3", "doubt.reason", "Not because it was hard, but because it bored you.", "Lo dejé no porque ___ difícil, sino porque me aburría.", ["era", "fuera"], [0, 1], "Both are used. The subjunctive marks the rejected reason clearly; era is also heard. The real reason (me aburría): indicative."),
        form("doubt.reason.4", "doubt.reason", "He didn't come; he was sick.", "No vino porque ___ enfermo.", ["estaba", "estuviera"], [0], "Here the no belongs to vino and porque gives the real reason: indicative."),

        // Believing
        form("belief.question.3", "belief.question", "You want your friend to agree.", "¿No crees que ___ muy tarde?", ["es", "sea"], [0], "Asking you to agree: indicative."),
        form("belief.askdoubt.1", "belief.askdoubt", "A neutral question about rain.", "¿Crees que ___ a llover?", ["va", "vaya"], [0, 1], "Both are right. The indicative is neutral; vaya shows you doubt it."),
        meaning("belief.askdoubt.2", "belief.askdoubt", "Your friend asks about your brother.", "¿Crees que venga?", ["They're asking, and they doubt it.", "They're sure he's coming."], 0, "The subjunctive in a question adds doubt."),
        meaning("belief.askdoubt.3", "belief.askdoubt", "Your friend asks about your brother.", "¿Crees que viene?", ["A neutral question.", "They've decided he isn't coming."], 0, "The indicative is the neutral way to ask."),
        form("belief.whether.1", "belief.whether", "You don't know whether he's coming.", "No sé si ___.", ["viene", "venga"], [0], "Si = whether isn't a trigger: indicative."),
        form("belief.whether.2", "belief.whether", "You don't know what to do.", "No sé qué ___.", ["hacer", "haga"], [0, 1], "Both are right. No sé qué hacer is the most common everywhere. No sé qué haga is used in Mexico (about 1 in 5 such questions in Mexico City, by educated and everyday speakers alike) and in Spain too."),
        form("belief.whether.3", "belief.whether", "He asked whether you'd go.", "Me preguntó si ___.", ["iría", "fuera"], [0], "Si = whether takes any tense that fits, even the conditional."),
        form("belief.parece.1", "belief.parece", "Dark clouds.", "Parece que ___ a llover.", ["va", "vaya"], [0], "Parece que: indicative."),
        form("belief.parece.2", "belief.parece", "It's hard to believe she's 40.", "Parece mentira que ya ___ 40 años.", ["tiene", "tenga"], [1], "Parece mentira que: subjunctive."),
        form("belief.parece.3", "belief.parece", "You're fine with your friend coming along.", "Me parece bien que ___ con nosotros.", ["vienes", "vengas"], [1], "Me parece bien que is a judgement: subjunctive."),

        form("belief.nouns.1", "belief.nouns", "You heard the news: she's pregnant.", "Me llegó la noticia de que ___ embarazada.", ["está", "esté"], [0], "News is information: indicative."),
        form("belief.nouns.2", "belief.nouns", "It might rain.", "Existe la posibilidad de que ___.", ["llueve", "llueva"], [1], "A possibility: subjunctive."),
        form("belief.nouns.3", "belief.nouns", "You can't wait for summer.", "Tengo ganas de que ___ el verano.", ["llega", "llegue"], [1], "A wish: subjunctive."),
        meaning("belief.nouns.4", "belief.nouns", "Making plans.", "Me gusta la idea de que vengas.", ["I like the idea of you coming (a proposal).", "I believe you're coming."], 0, "La idea de que + subjunctive: a proposal."),

        // Impersonal
        form("impersonal.3", "impersonal", "You must sign here.", "Es necesario que ___ aquí.", ["firmas", "firmes"], [1], "Need: subjunctive."),
        form("impersonal.truth.3", "impersonal.truth", "It's true it's expensive.", "Es cierto que ___ caro.", ["es", "sea"], [0], "Truth: indicative."),
        form("impersonal.puede.3", "impersonal.puede", "Maybe he'll be late.", "A lo mejor ___ tarde.", ["llega", "llegue"], [0, 1], "Both occur: llega is the norm (about 98%); llegue is heard, mostly in Latin America."),
        form("impersonal.agree.1", "impersonal.agree", "You want your friend to agree she's gorgeous.", "¿No es verdad que ___ guapísima?", ["es", "sea"], [0], "Asking to agree: indicative."),
        form("impersonal.agree.2", "impersonal.agree", "You deny you said it.", "No es verdad que lo ___ dicho.", ["he", "haya"], [1], "Rejected: subjunctive."),
        form("impersonal.agree.3", "impersonal.agree", "It isn't obvious he's lying.", "No es obvio que ___.", ["miente", "mienta"], [1], "No es obvio que: subjunctive."),

        // Known or unknown
        form("unknown.none.3", "unknown.none", "Nothing here appeals to you.", "No hay nada que me ___.", ["gusta", "guste"], [1], "Something that doesn't exist: subjunctive."),
        form("unknown.superlative.2", "unknown.superlative", "Your best friend.", "Eres la única persona que me ___.", ["entiende", "entienda"], [0, 1], "After el único, both work; the subjunctive adds emphasis."),
        meaning("unknown.superlative.3", "unknown.superlative", "Talking about a book.", "Es el mejor libro que haya leído.", ["The best I've ever read (emphatic).", "I haven't read it yet."], 0, "The subjunctive after a superlative adds emphasis; he leído is the plain way."),
        form("unknown.ask.1", "unknown.ask", "You need anyone who speaks Japanese.", "¿Conoces a alguien que ___ japonés?", ["habla", "hable"], [0, 1], "Both are right. Hable asks openly whether such a person exists; habla assumes there is one."),
        form("unknown.ask.2", "unknown.ask", "Very few people can do it.", "Hay pocas personas que lo ___ hacer.", ["saben", "sepan"], [0, 1], "Both are right. Sepan stresses that there are almost none; saben just describes them."),
        form("unknown.ask.5", "unknown.ask", "Almost nobody came.", "Sé de pocos que ___ venido.", ["han", "hayan"], [1], "Pocos = almost none: subjunctive."),
        form("unknown.ask.3", "unknown.ask", "Any Russian speaker will do.", "Busco a alguien que ___ ruso.", ["habla", "hable"], [1], "The personal a doesn't make the person known: subjunctive."),
        form("unknown.ask.4", "unknown.ask", "You know the guy: he speaks Russian.", "Busco al chico que ___ ruso.", ["habla", "hable"], [0], "A specific person you know: indicative."),
        form("unknown.superlative.4", "unknown.superlative", "Whoever arrives first opens up.", "El primero que ___, abre la puerta.", ["llega", "llegue"], [1], "Nobody knows who it will be: subjunctive."),
        form("unknown.free.1", "unknown.free", "Do whatever you want.", "Haz lo que ___.", ["quieres", "quieras"], [1], "Open, whatever it is: subjunctive."),
        form("unknown.free.2", "unknown.free", "You did exactly what she said.", "Hice lo que me ___.", ["dijo", "dijera"], [0], "Known and past: indicative."),
        meaning("unknown.free.3", "unknown.free", "Ending an argument.", "Como tú digas.", ["Whatever you say.", "As you're saying."], 0, "Como + subjunctive: however, whatever. Como tú dices = as you say."),
        form("unknown.free.4", "unknown.free", "Put it wherever you like.", "Ponlo donde ___.", ["quieres", "quieras"], [1], "Wherever: subjunctive."),
        form("unknown.free.5", "unknown.free", "Advice to a student.", "Cuanto más ___, más aprenderás.", ["estudias", "estudies"], [1], "Cuanto más about the future: subjunctive."),
        form("unknown.quiera.1", "unknown.quiera", "Whoever it is, don't open.", "Quienquiera que ___, no abras.", ["es", "sea"], [1], "Quienquiera que: subjunctive."),
        form("unknown.quiera.2", "unknown.quiera", "Anyone who wants to come, should come.", "Todo el que ___ venir, que venga.", ["quiere", "quiera"], [1], "Todo el que + something open: subjunctive."),
        form("unknown.quiera.3", "unknown.quiera", "Anything you need, call me.", "Cualquier cosa que ___, llámame.", ["necesitas", "necesites"], [1], "Cualquier… que: subjunctive."),

        // Time
        form("time.before.3", "time.before", "You got there before the film started.", "Llegamos antes de que ___ la película.", ["empezó", "empezara"], [1], "Antes de que: always subjunctive, even in the past."),
        form("time.question.2", "time.question", "You ask when your friend is coming.", "¿Cuándo ___?", ["vienes", "vengas"], [0], "A question with ¿cuándo?: indicative."),
        form("time.question.3", "time.question", "Let me know when you arrive.", "Avísame cuando ___.", ["llegas", "llegues"], [1], "Not a question: a time clause about the future, subjunctive."),
        form("time.despues.2", "time.despues", "After you leave, I'll clean.", "Después de que te ___, limpio.", ["vas", "vayas"], [1], "Still to come: subjunctive."),
        form("time.despues.3", "time.despues", "Yesterday, after sunset, we went out.", "Después de que se ___ el sol, salimos.", ["puso", "pusiera"], [0, 1], "In the past both are accepted; the indicative is the everyday one."),
        form("time.never.1", "time.never", "When you have time, you'll visit.", "Cuando ___ tiempo, te visito.", ["tendré", "tenga"], [1], "Never the future after cuando: subjunctive."),
        form("time.never.2", "time.never", "He said he'd come when he could.", "Dijo que vendría cuando ___.", ["podría", "pudiera"], [1], "Never the conditional after cuando: imperfect subjunctive."),
        form("time.never.3", "time.never", "As soon as you know, you'll call.", "En cuanto lo ___, te llamo.", ["sabré", "sepa"], [1], "En cuanto + still to come: subjunctive."),
        form("time.mientras.1", "time.mientras", "While you cook, I set the table.", "Mientras ___, pongo la mesa.", ["cocinas", "cocines"], [0], "Mientras = while: indicative."),
        form("time.mientras.2", "time.mientras", "As long as they pay you, you'll stay.", "Mientras me ___, me quedo.", ["pagan", "paguen"], [1], "Mientras = as long as: subjunctive."),
        form("time.mientras.3", "time.mientras", "Whenever she comes, she brings bread.", "Siempre que ___, trae pan.", ["viene", "venga"], [0], "Siempre que = whenever: indicative."),
        form("time.mientras.4", "time.mientras", "You'll lend it, provided they return it.", "Te lo presto siempre que me lo ___.", ["devuelves", "devuelvas"], [1], "Siempre que = provided that: subjunctive."),
        form("time.desde.1", "time.desde", "Since you met her, you're happy.", "Desde que la ___, soy feliz.", ["conocí", "conociera"], [0], "Desde que: indicative."),
        form("time.desde.2", "time.desde", "Since you've lived here, things are better.", "Desde que ___ aquí, todo va mejor.", ["vivo", "viva"], [0], "Desde que: indicative."),
        form("time.desde.4", "time.desde", "From the moment you land.", "Desde que ___ hasta que llegues al hotel, avísame.", ["aterrizas", "aterrices"], [1], "A future starting point: subjunctive."),
        meaning("time.desde.3", "time.desde", "Kids talking about their mom.", "No salimos hasta que no nos lo pida.", ["We won't go out until she asks.", "We'll go out unless she asks."], 0, "In hasta que no, the no adds nothing."),

        // Conditions
        form("condition.si.3", "condition.si", "You don't have money; imagining.", "Si ___ dinero, viajaría.", ["tengo", "tuviera"], [1], "Unreal now: si + imperfect subjunctive."),
        form("condition.unreal.1", "condition.unreal", "You didn't know.", "Si lo ___ sabido, te habría avisado.", ["había", "hubiera"], [1], "Didn't happen: si + pluperfect subjunctive."),
        form("condition.unreal.2", "condition.unreal", "The result of what didn't happen.", "Si me lo hubieras dicho, ___ venido.", ["habría", "hubiera", "habré"], [0, 1], "Both habría and hubiera work in the result."),
        form("condition.unreal.3", "condition.unreal", "You didn't study, and now you have no job.", "Si hubiera estudiado, ahora ___ trabajo.", ["tendría", "tuviera"], [0], "Past condition, present result: the conditional."),
        form("condition.others.1", "condition.others", "You'll go unless it rains.", "Voy a menos que ___.", ["llueve", "llueva"], [1], "A menos que: subjunctive."),
        form("condition.others.2", "condition.others", "You'll lend it, as long as they return it.", "Te lo presto con tal de que me lo ___.", ["devuelves", "devuelvas"], [1], "Con tal de que: subjunctive."),
        form("condition.others.3", "condition.others", "See you tomorrow, unless something happens.", "A no ser que ___ algo, nos vemos mañana.", ["pasa", "pase"], [1], "A no ser que: subjunctive."),
        form("condition.others.4", "condition.others", "A great trip, except the hotel was expensive.", "Todo bien, salvo que el hotel ___ caro.", ["era", "fuera"], [0], "Salvo que = except that, a fact: indicative."),
        form("condition.como.3", "condition.como", "Since you didn't call, you left.", "Como no ___, me fui.", ["llamaste", "llamaras"], [0], "Como = since: indicative."),
        form("condition.porsi.2", "condition.porsi", "In case it gets cold.", "Por si ___ frío, llévate un suéter.", ["hace", "haga"], [0], "Por si: indicative, never the present subjunctive."),
        form("condition.porsi.3", "condition.porsi", "In case it rains (not very likely).", "Llévate un paraguas por si ___.", ["llueva", "lloviera"], [1], "Por si + less likely: imperfect subjunctive. Never the present subjunctive."),
        meaning("condition.de.1", "condition.de", "Looking back.", "De haberlo sabido, habría venido.", ["If I had known, I'd have come.", "Since I knew, I came."], 0, "De + infinitive works like si."),
        meaning("condition.de.2", "condition.de", "Encouraging a friend.", "Insiste y lo conseguirás.", ["If you insist, you'll get it.", "You insisted and got it."], 0, "A command + y works as a condition."),
        meaning("condition.de.3", "condition.de", "Advice in speech.", "Yo que tú, me iba.", ["If I were you, I'd leave.", "I left before you."], 0, "Spoken: yo que tú + imperfect, = yo en tu lugar me iría."),

        // Purpose and results
        form("purpose.3", "purpose", "You call so they'll help you.", "Te llamo para que me ___.", ["ayudas", "ayudes"], [1], "Para que: subjunctive."),
        form("purpose.comosi.3", "purpose.comosi", "As if you were a millionaire!", "¡Ni que ___ millonario!", ["eres", "fueras"], [1], "Ni que, like como si: imperfect subjunctive."),
        form("purpose.demodo.3", "purpose.demodo", "You were tired, so you slept.", "Estaba cansado, así que me ___.", ["dormí", "durmiera"], [0], "Así que gives a result: indicative."),
        form("purpose.nosea.1", "purpose.nosea", "Take a coat in case it gets cold.", "Llévate abrigo, no sea que ___ frío.", ["hace", "haga"], [1], "No sea que: subjunctive."),
        form("purpose.nosea.2", "purpose.nosea", "You came for them to help you.", "Vengo a que me ___.", ["ayudas", "ayudes"], [1], "Venir a que: purpose, subjunctive."),
        form("purpose.nosea.3", "purpose.nosea", "Come here so I can see you.", "Ven aquí, que te ___.", ["veo", "vea"], [1], "Que after a command = so that: subjunctive."),
        form("purpose.nosea.4", "purpose.nosea", "Put a coat on, because it's cold.", "Abrígate, que ___ frío.", ["hace", "haga"], [0], "Here que means because: indicative."),
        form("purpose.result.1", "purpose.result", "He ate so much he got sick.", "Comió tanto que se ___.", ["enfermó", "enfermara"], [0], "A result that happened: indicative."),
        form("purpose.result.2", "purpose.result", "He isn't so rich he can buy everything.", "No es tan rico que ___ comprarlo todo.", ["puede", "pueda"], [1], "A denied result: subjunctive."),
        form("purpose.result.3", "purpose.result", "It was late, so you left.", "Era tarde, por eso me ___.", ["fui", "fuera"], [0], "Por eso: indicative."),

        // Even though
        form("concession.3", "concession", "Even if it rains tomorrow, you'll go.", "Aunque ___ mañana, vamos.", ["llueve", "llueva"], [1], "A possibility: subjunctive."),
        form("concession.waved.2", "concession.waved", "He is your boss, but still.", "Aunque ___ tu jefe, no le hables así.", ["es", "sea"], [0, 1], "Known fact: the indicative states it, the subjunctive waves it away."),
        meaning("concession.waved.3", "concession.waved", "In a shop.", "Aunque sea caro, lo compro.", ["Pricey or not (or: yes, it's pricey, so what), I'll buy it.", "It's definitely cheap."], 0, "Aunque + subjunctive: it doesn't matter."),
        form("concession.pormas.3", "concession.pormas", "No matter how much you talk.", "Por mucho que ___, no lo vas a convencer.", ["hablas", "hables"], [1], "Por mucho que: subjunctive."),
        form("concession.pormas.4", "concession.pormas", "You really tried, and couldn't.", "Por más que lo ___, no pude.", ["intenté", "intentara"], [0, 1], "Both are right for a real effort: the indicative states it, the subjunctive waves it away."),
        form("concession.unreal.1", "concession.unreal", "Even if you'd told me, I wouldn't have gone.", "Aunque me lo ___ dicho, no habría ido.", ["habías", "hubieras"], [1], "Didn't happen: pluperfect subjunctive."),
        form("concession.unreal.2", "concession.unreal", "Even if you were rich, you wouldn't buy it.", "Aunque ___ rico, no lo compraría.", ["soy", "fuera"], [1], "Unreal: imperfect subjunctive."),
        form("concession.unreal.3", "concession.unreal", "He was tired but kept going.", "A pesar de que ___ cansado, siguió.", ["estaba", "estuviera"], [0], "A pesar de que with a fact: indicative."),
        form("concession.sibien.1", "concession.sibien", "It's expensive, but worth it.", "Si bien ___ caro, vale la pena.", ["es", "sea"], [0], "Si bien: indicative."),
        form("concession.sibien.2", "concession.sibien", "He failed, even though he studied.", "Suspendió, y eso que ___.", ["estudió", "estudiara"], [0], "Y eso que: indicative."),
        meaning("concession.sibien.3", "concession.sibien", "You'll hear in Latin America.", "Así llueva, salimos.", ["Even if it rains, we go out.", "As it rains, we go out."], 0, "Así + subjunctive = even if, in Latin American speech."),

        // On its own
        form("alone.2", "alone", "Maybe you're right.", "Quizás ___ razón.", ["tienes", "tengas"], [0, 1], "Before the verb, quizás takes either mood."),
        meaning("alone.3", "alone", "Before a meal.", "¡Que aproveche!", ["Enjoy your meal!", "What a meal!"], 0, "Que + subjunctive: a wish."),
        form("alone.ojala.3", "alone.ojala", "You don't have more time.", "Ojalá ___ más tiempo.", ["tengo", "tuviera"], [1], "Unlikely or untrue: ojalá + imperfect subjunctive."),
        form("alone.que.2", "alone.que", "Saying goodbye.", "¡Que te ___ bien!", ["va", "vaya"], [1], "A wish: subjunctive."),
        meaning("alone.que.4", "alone.que", "A child shouting in a story.", "¡Que viene el lobo!", ["The wolf is coming! (a warning)", "May the wolf come!"], 0, "Que + indicative on its own is a warning, not a wish."),
        form("alone.que.3", "alone.que", "Calling the next person in.", "¡Que ___ el siguiente!", ["pasa", "pase"], [1], "An order passed on: subjunctive."),
        form("alone.quizas.3", "alone.quizas", "You're not very sure.", "Tal vez ___ tarde.", ["llega", "llegue"], [0, 1], "Before the verb, tal vez takes either mood; the subjunctive is less sure."),
        form("alone.commands.1", "alone.commands", "Tell your friend not to talk.", "No ___.", ["hablas", "hables"], [1], "A negative command: subjunctive forms."),
        form("alone.commands.2", "alone.commands", "Ask your teacher (usted) to sit.", "___, por favor.", ["Siéntate", "Siéntese"], [1], "Usted command: siéntese. Siéntate is for tú."),
        form("alone.commands.3", "alone.commands", "Tell your friends (ustedes) not to worry.", "No se ___.", ["preocupan", "preocupen"], [1], "Negative ustedes command: subjunctive."),
        meaning("alone.polite.1", "alone.polite", "At a café.", "Quisiera un café.", ["I'd like a coffee (polite).", "I wanted a coffee."], 0, "Quisiera softens a request."),
        meaning("alone.polite.2", "alone.polite", "Asking a stranger.", "¿Pudiera ayudarme?", ["Could you help me? (polite)", "Did you help me?"], 0, "Pudiera works as a polite could, but ¿podría ayudarme? is more common everywhere, Mexico included."),
        meaning("alone.polite.3", "alone.polite", "At a café.", "Quisiese un café.", ["The RAE rejects it here: say quisiera.", "The usual polite form."], 0, "Only -ra works as a polite request. -se turns up in jokes (¡qué más quisieses!) but isn't the norm."),
        meaning("alone.mexico.2", "alone.mexico", "A friend in Mexico City.", "¡Qué bueno que viniste!", ["Heard in Latin American speech, to stress the fact; the usual form is qué bueno que hayas venido.", "Wrong everywhere."], 0, "The RAE records the indicative after feelings, more in Latin America, to highlight the information. Only for real facts, never the future. The app uses the subjunctive."),
        meaning("alone.mexico.3", "alone.mexico", "A friend in Mexico.", "No sé qué haga.", ["I don't know what to do (said a lot in Mexico).", "I don't know what he did."], 0, "In Mexico the present subjunctive often replaces the future after no sé si / qué, for now or later, never the past: no sé si los protejan. Not colloquial: educated speakers use it as much."),
        meaning("alone.mexico.6", "alone.mexico", "A sign on a shop in Mexico City.", "Abrimos hasta las diez.", ["We open at ten (not before).", "We're open until ten."], 0, "In Mexico and Colombia, hasta often means not until."),
        meaning("alone.mexico.5", "alone.mexico", "In Medellín.", "No digás eso.", ["Colombian voseo for no digas eso.", "A typo."], 0, "Voseo in Antioquia and Valle del Cauca: cantés, digás, comé. The app uses tú."),
        meaning("alone.mexico.4", "alone.mexico", "You'll hear in Latin America.", "Capaz que llueve.", ["Maybe it'll rain.", "It's able to rain."], 0, "Capaz que = maybe, usually with the indicative."),

        // Tense sequence
        form("sequence.past.3", "sequence.past", "You asked him to help.", "Le pedí que me ___.", ["ayuda", "ayudara"], [1], "Past main verb: imperfect subjunctive."),
        form("sequence.conditional.2", "sequence.conditional", "It would be better for you to stay.", "Sería mejor que te ___.", ["quedes", "quedaras"], [1], "Conditional main verb: imperfect subjunctive."),
        form("sequence.conditional.3", "sequence.conditional", "You'd like them to call more.", "Me gustaría que me ___ más.", ["llamen", "llamaran"], [1], "Me gustaría que + imperfect subjunctive."),
        meaning("sequence.pending.2", "sequence.pending", "You'll hear in Latin America.", "Mandaron que estudie.", ["They ordered him to study (still to happen); standard: que estudiara.", "Wrong everywhere."], 0, "Past verb + present subjunctive for something still to come is common in Latin America."),
        form("sequence.earlier.1", "sequence.earlier", "They traveled; you hope they arrived well.", "Espero que ___ llegado bien.", ["han", "hayan"], [1], "Earlier than a present main verb: haya + participle."),
        form("sequence.earlier.2", "sequence.earlier", "You didn't think he had done it.", "No creía que lo ___ hecho.", ["había", "hubiera"], [1], "Earlier than a past main verb: hubiera + participle."),
        form("sequence.earlier.3", "sequence.earlier", "You doubted he had studied.", "Dudaba que ___ estudiado.", ["ha", "hubiera"], [1], "Past doubt about something earlier: pluperfect subjunctive."),
        form("sequence.presentpast.1", "sequence.presentpast", "You don't think he lied yesterday.", "No creo que ___ ayer.", ["mintió", "mintiera", "haya mentido"], [1, 2], "Present main verb, past event: mintiera and haya mentido both work."),
        form("sequence.presentpast.2", "sequence.presentpast", "Maybe he's already left.", "Es posible que ya ___.", ["salió", "haya salido"], [1], "Es posible que + a past event: perfect subjunctive."),
        form("sequence.presentpast.3", "sequence.presentpast", "He didn't call last night; that surprises you.", "Me sorprende que no ___ anoche.", ["llamó", "llamara"], [1], "Present feeling about a past event: imperfect subjunctive works."),
        form("sequence.feelpast.1", "sequence.feelpast", "She was sorry he hadn't liked it.", "Lamentó que no le ___ gustado.", ["habría", "hubiera"], [1], "After a feeling: hubiera, never habría."),
        form("sequence.feelpast.2", "sequence.feelpast", "It hurt that they hadn't invited you.", "Me dolió que no me ___ invitado.", ["habrían", "hubieran"], [1], "After a feeling: hubieran."),
        form("sequence.feelpast.3", "sequence.feelpast", "It bothered him that you hadn't warned him.", "Le molestó que no le ___ avisado.", ["habíamos", "hubiéramos"], [1], "A feeling about something earlier: pluperfect subjunctive."),
        meaning("sequence.forms.1", "sequence.forms", "Reading a book from Spain.", "Si tuviese tiempo, iría.", ["Same as si tuviera tiempo.", "A mistake."], 0, "-ra and -se are the same subjunctive."),
        meaning("sequence.forms.2", "sequence.forms", "A set phrase.", "Sea lo que fuere.", ["Whatever it may be (= sea lo que sea).", "A typo."], 0, "Fuere is the old future subjunctive, alive only in set phrases."),
        meaning("sequence.forms.3", "sequence.forms", "On an official form.", "Si fuere necesario, llame.", ["Legal style for si es necesario.", "If it was necessary."], 0, "Today: si es necesario."),

        // Lessons that had fewer than three cards
        form("feel.3", "feel", "You're worried your son doesn't eat.", "Me preocupa que mi hijo no ___.", ["come", "coma"], [1], "A feeling about it: subjunctive."),
        form("doubt.3", "doubt", "You doubt they'll arrive on time.", "Dudo que ___ a tiempo.", ["llegan", "lleguen"], [1], "Doubt: subjunctive."),
        form("belief.3", "belief", "You saw it: it's raining.", "Veo que ___.", ["llueve", "llueva"], [0], "Seeing is a claim: indicative."),
        form("sequence.2", "sequence", "You wanted your friend to come.", "Quería que ___.", ["vengas", "vinieras"], [1], "Past main verb: imperfect subjunctive."),
        form("sequence.3", "sequence", "You want your friend to come.", "Quiero que ___.", ["vengas", "vinieras"], [0], "Present main verb: present subjunctive."),
        form("purpose.deahi.2", "purpose.deahi", "He studied a lot; that's why he passed.", "Estudió mucho; de ahí que ___.", ["aprobó", "aprobara"], [1], "De ahí que: subjunctive, even for a known result."),
        form("purpose.deahi.3", "purpose.deahi", "Prices went up; hence people buy less.", "Subieron los precios; de ahí que la gente ___ menos.", ["compra", "compre"], [1], "De ahí que: subjunctive."),
        meaning("sequence.pending.3", "sequence.pending", "Your boss, in Mexico.", "Me dijo que lo llame mañana.", ["Heard when it's still to come; standard: que lo llamara.", "Wrong everywhere."], 0, "Past verb + present subjunctive for something still pending: common in Latin America."),

        // Set phrases
        form("fixed.1", "fixed", "No matter what happens, you'll be there.", "Pase lo que ___, estaré ahí.", ["pasa", "pase"], [1], "Doubled verb: subjunctive."),
        form("fixed.2", "fixed", "Like it or not.", "Te ___ o no, vamos.", ["gusta", "guste"], [1], "Te guste o no: subjunctive."),
        form("fixed.3", "fixed", "As far as you know.", "Que yo ___, no viene.", ["sé", "sepa"], [1], "Que yo sepa: subjunctive."),
        form("fixed.double.1", "fixed.double", "Whatever he says, you don't believe him.", "Diga lo que ___, no le creo.", ["dice", "diga"], [1], "Both verbs match: subjunctive."),
        form("fixed.double.2", "fixed.double", "In the past: whatever happened, we kept going.", "Pasara lo que ___, seguimos.", ["pasaba", "pasara"], [1], "Past: both in the imperfect subjunctive."),
        form("fixed.double.3", "fixed.double", "One way or another, we'll finish it.", "Sea como ___, lo terminamos.", ["es", "sea"], [1], "Sea como sea: subjunctive."),
        form("fixed.double.4", "fixed.double", "Whatever it costs.", "Cueste lo que ___.", ["cuesta", "cueste"], [1], "Cueste lo que cueste."),
        form("fixed.hedge.1", "fixed.hedge", "As far as you remember, nobody called.", "Que yo ___, nadie llamó.", ["recuerdo", "recuerde"], [1], "Que yo recuerde: subjunctive."),
        meaning("fixed.hedge.2", "fixed.hedge", "About someone.", "No es muy listo, que digamos.", ["He isn't exactly smart.", "Let's say he's smart."], 0, "Que digamos adds 'not exactly'."),
        meaning("fixed.hedge.3", "fixed.hedge", "Making a plan.", "Digamos que llego a las ocho.", ["Let's say I get there at eight.", "I said I'd get there at eight."], 0, "Digamos que = let's say."),
        meaning("fixed.frozen.1", "fixed.frozen", "Independence Day.", "¡Viva México!", ["Long live Mexico!", "Mexico is alive."], 0, "A frozen wish in the subjunctive."),
        meaning("fixed.frozen.2", "fixed.frozen", "At a funeral.", "Que en paz descanse.", ["May he rest in peace.", "He rests in peace."], 0, "Que + subjunctive: a wish."),
        meaning("fixed.frozen.3", "fixed.frozen", "At the end of a prayer.", "Así sea.", ["So be it.", "That's how it is."], 0, "Así + subjunctive: a wish."),
        // Present → imperfect subjunctive
        form("imperfect.2", "imperfect", "Last year your parents had a plan for you.", "Mis papás querían que ___ medicina.", ["estudie", "estudiara"], [1], "Querían is past, so the subjunctive moves back: estudiara. Today: quieren que estudie."),
        form("imperfect.3", "imperfect", "Your parents' plan, today.", "Mis papás quieren que ___ medicina.", ["estudie", "estudiara"], [0], "Quieren is present: present subjunctive, estudie. Last year: querían que estudiara."),
        meaning("imperfect.4", "imperfect", "Two moments.", "Esperaba que llegara.", ["I was hoping she'd arrive.", "I hope she arrives."], 0, "Esperaba is past, and llegara moves back with it. I hope she arrives is espero que llegue."),
        form("imperfect.make.1", "imperfect.make", "Tener: ellos tuvieron → tuvie-.", "Ojalá ___ más tiempo.", ["tuviera", "tenía"], [0], "From the ellos preterite: tuvieron → tuviera. Tenía is the imperfect indicative, a different mood."),
        form("imperfect.make.2", "imperfect.make", "Ser: ellos fueron → fue-.", "Si ___ rico, viajaría.", ["fuera", "era"], [0], "Fueron → fuera, for ser and ir alike. Era is the imperfect indicative, which si can't take for something unreal."),
        form("imperfect.make.3", "imperfect.make", "Decir: ellos dijeron → dije-.", "Me pidió que se lo ___.", ["dijera", "decía"], [0], "Dijeron → dijera: the irregular preterite carries over. Decía is the imperfect indicative."),
        form("imperfect.make.4", "imperfect.make", "Llegar, nosotros: llegaron → llegá-ramos.", "Querían que ___ temprano.", ["llegáramos", "llegábamos"], [0], "Nosotros gets an accent: llegáramos. Llegábamos is the imperfect indicative."),
        form("imperfect.unreal.1", "imperfect.unreal", "You don't have time right now.", "Si ___ tiempo, te ayudaría.", ["tengo", "tuviera"], [1], "Not real now: si + imperfect subjunctive, with the conditional (ayudaría). There's no past here, just something that isn't so."),
        form("imperfect.unreal.2", "imperfect.unreal", "You can still win the game tomorrow.", "Ojalá ___ mañana.", ["ganemos", "ganáramos"], [0], "It can happen, so the present subjunctive. Ojalá ganáramos would sound like you probably won't."),
        form("imperfect.unreal.3", "imperfect.unreal", "It's Monday, and you wish it weren't.", "Ojalá ___ viernes.", ["sea", "fuera"], [1], "It isn't Friday: ojalá + imperfect subjunctive for something that can't be so right now."),
        form("imperfect.unreal.4", "imperfect.unreal", "He isn't the boss.", "Habla como si ___ el jefe.", ["es", "fuera"], [1], "Como si always takes a past subjunctive: it compares with something that isn't so."),
        meaning("imperfect.english.1", "imperfect.english", "Your friend, about last night.", "Quería que vinieras.", ["I wanted you to come.", "I wanted to come."], 0, "Que + another person: I wanted you to come. I wanted to come is quería venir."),
        meaning("imperfect.english.2", "imperfect.english", "A friend explains.", "Si tuviera tiempo, iría.", ["If I had time, I'd go.", "If I have time, I'll go."], 0, "Si + imperfect subjunctive is English if I had: not real. If I have time is si tengo tiempo."),
        meaning("imperfect.english.3", "imperfect.english", "Your sister is away.", "Ojalá estuviera aquí.", ["I wish she were here.", "I hope she's here."], 0, "Ojalá + imperfect subjunctive is I wish… were. I hope she's here is ojalá esté aquí."),
        meaning("imperfect.english.4", "imperfect.english", "Your mom, about your brother.", "Me pidió que lo llamara.", ["She asked me to call him.", "She asked if I had called him."], 0, "Pedir que + subjunctive is asking someone to do something: she asked me to call him."),
        form("sequence.haber.1", "sequence", "They traveled; you hope they got there.", "Espero que ___ llegado bien.", ["hayan", "hubieran"], [0], "Present main verb, something already done: haya + participle."),
        form("sequence.haber.2", "sequence", "Yesterday you were hoping they'd got there.", "Esperaba que ___ llegado bien.", ["hayan", "hubieran"], [1], "Past main verb, something done before it: hubiera + participle."),
        form("sequence.haber.3", "sequence", "You don't think he's done it.", "No creo que lo ___ hecho.", ["haya", "hubiera"], [0], "No creo is present: haya hecho. In the past: no creía que lo hubiera hecho."),
    ]
}
